export class Contact {
    /**
     * Prove I own the address on this report
     *
     * Completes double opt-in. Until it succeeds the report is
     * `PENDING_VERIFICATION` and is held out of every triage, assignment and
     * SLA queue - the verification gate is what stops the contact channel
     * being used to make a stranger receive mail about a problem they never
     * reported.
     *
     * Deliberately answers 204 with an empty body on success: it must not
     * echo the address back, because a response that returns the address is a
     * response that will end up in a log.
     *
     */
    public static verifyContact<ThrowOnError extends boolean = false>(options: Options<VerifyContactData, ThrowOnError>): RequestResult<VerifyContactResponses, VerifyContactErrors, ThrowOnError> {
        return (options.client ?? client).post<VerifyContactResponses, VerifyContactErrors, ThrowOnError>({ url: '/contact/verify', ...options });
    }
    
    /**
     * Approve the officer's fix, or dispute it
     *
     * The approval gate. An officer's `POST /issues/{id}/resolve` proposes a
     * fix; nothing is `CLOSED` until the reporter answers here, and the answer
     * may be `DISPUTE`, which sends the report to `REOPENED` with the reason
     * attached.
     *
     * **This gate is the same for every reporter.** Concealment changes who can
     * *see* the reporter; it does not change the lifecycle. One rule is easier
     * to explain to a citizen, easier to test exhaustively, and stops the
     * close path from having two subtly different branches depending on a
     * disclosure flag.
     *
     * Works for concealed reporters with no account, and for signed-in ones
     * too - the signed-in path keeps `POST /issues/{id}/confirm` and
     * `/reopen`, which do the same thing through the session. Both write the
     * same audit row.
     *
     */
    public static submitContactDecision<ThrowOnError extends boolean = false>(options: Options<SubmitContactDecisionData, ThrowOnError>): RequestResult<SubmitContactDecisionResponses, SubmitContactDecisionErrors, ThrowOnError> {
        return (options.client ?? client).post<SubmitContactDecisionResponses, SubmitContactDecisionErrors, ThrowOnError>({
            url: '/contact/decision',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
}

export class Public {
    /**
     * Public shareable issue page
     *
     * The one unauthenticated read surface, for a shareable link a citizen
     * can send to a neighbour or a councillor.
     *
     * The response is a dedicated redacted type built from an explicit field
     * allowlist. It is NOT the internal issue DTO with fields nulled, because
     * that pattern leaks on the next field someone adds. Never expose reporter
     * identity, exact coordinates or exact address on private property,
     * comment bodies, internal notes, duplicate candidates or AI reasoning.
     *
     * `publicCode` is a share handle, not a credential. It is a dense
     * sequential range, so this endpoint is rate limited per IP and must stay
     * that way: a public code in a chat message is a real thing people will
     * paste, and the range behind it is walkable.
     *
     * **Title redaction for concealed reports.** When the reporter chose
     * `disclosure: CONCEALED`, `title` is replaced with the category name and
     * `titleRedacted` is true. A citizen's own words are frequently the
     * identifying detail — "my gate is broken, I am at house number 12" — so
     * publishing the title of a concealed report can deanonymize it just as
     * effectively as publishing a name. The flag is returned so the page can
     * render it honestly rather than presenting redacted text as if it were
     * what was written. Note this reveals that a report is concealed, which is
     * a far smaller disclosure than revealing who wrote it.
     *
     * Rate limited to 60 requests per minute per IP.
     *
     */
    public static getPublicIssue<ThrowOnError extends boolean = false>(options: Options<GetPublicIssueData, ThrowOnError>): RequestResult<GetPublicIssueResponses, GetPublicIssueErrors, ThrowOnError> {
        return (options.client ?? client).get<GetPublicIssueResponses, GetPublicIssueErrors, ThrowOnError>({ url: '/public/issues/{publicCode}', ...options });
    }
}

